def solve(nums):
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # find insertion point in tails for x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

