def solve(lst):
    """Flatten a nested list of integers to a flat list preserving order.
    Elements may be int or list (nested arbitrarily). Return list of ints.
    """
    result = []
    def helper(item):
        if isinstance(item, list):
            for sub in item:
                helper(sub)
        else:
            # assuming item is int
            result.append(item)
    helper(lst)
    return result

def solve(line: str):
    """Parse a single CSV line into fields.
    Implements RFC 4180 behavior for the limited features required:
    - Fields may be quoted with double quotes.
    - Inside quoted fields, a pair of double quotes represents a literal quote.
    - Commas inside quoted fields are treated as data.
    - Spaces (or other whitespace) after a closing quote up to the next comma are ignored.
    - An empty line yields [''].
    """
    if line == "":
        return [""]
    fields = []
    field = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # possible end of quoted field or escaped quote
                if i + 1 < n and line[i+1] == '"':
                    field.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quotes = False
                # continue to next character
            else:
                field.append(ch)
        else:
            if ch == '"':
                # start of quoted field (only if field is currently empty)
                if not field:
                    in_quotes = True
                else:
                    # stray quote inside unquoted field, treat as literal
                    field.append(ch)
            elif ch == ',':
                # end of field
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        # If we just closed a quoted field, skip any whitespace up to a comma or end
        if not in_quotes and field is not None:
            # Peek ahead only when we are at boundary after a closing quote
            # This check runs after processing a character that may have closed a quote
            j = i + 1
            while j < n and line[j] in ' \t':
