    # Parse CSV line according to simple RFC rules: fields optionally quoted with double quotes.
    # Inside quoted fields, double double-quote represents a literal quote. Commas inside quotes are data.
    if line == "":
        return [""]
    fields = []
    i = 0
    n = len(line)
    while i <= n:
        # If we are at end (i == n), add empty field (for trailing comma case) and break
        if i == n:
            fields.append('')
            break
        if line[i] == '"':
            # Quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # Could be escaped quote or end
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1  # consume closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            # After closing quote, expect comma or end
            # Skip any characters until comma or end (though spec doesn't allow extra)
            while i < n and line[i] != ',':
                # Skip unexpected characters (including spaces) before comma
                i += 1
            fields.append(''.join(field_chars))
            # If current char is comma, skip it and continue to next field
            if i < n and line[i] == ',':
                i += 1
                continue
            else:
                # End of string
                break
        else:
            # Unquoted field: read until comma
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
                continue
            else:
                break
    return fields
