def solve(s: str) -> str:
    n = len(s)
    if n == 0:
        return ''
    best_start = 0
    best_len = 1
    def expand(l: int, r: int) -> (int, int):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1
    for i in range(n):
        l1, r1 = expand(i, i)
        cur_len = r1 - l1 + 1
        if cur_len > best_len or (cur_len == best_len and l1 < best_start):
            best_len = cur_len
            best_start = l1
        l2, r2 = expand(i, i+1)
        cur_len = r2 - l2 + 1
        if cur_len > best_len or (cur_len == best_len and l2 < best_start):
            best_len = cur_len
            best_start = l2
    return s[best_start:best_start+best_len]

