def solve(matrix):
    """Compute the determinant of a square integer matrix using the
    fraction‑free Bareiss algorithm (O(n^3) time, exact integer arithmetic).
    An empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Base cases
    if n == 1:
        return matrix[0][0]
    if n == 2:
        a, b = matrix[0]
        c, d = matrix[1]
        return a * d - b * c
    # Create a mutable copy
    A = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivot handling: if pivot is zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update (exact division)
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            # Zero out the current column below the pivot
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]

