def solve(grid):
    """Count islands (connected groups of 1s) in a possibly irregular grid.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    n = len(grid)
    # visited mirrors shape of grid
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore four neighbours, checking bounds for each row
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        row_len = len(grid[i])
        for j in range(row_len):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

