def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Implements O(n^2) DP for simplicity and correctness.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n
    for i in range(1, n):
        best = 1
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > best:
                best = dp[j] + 1
        dp[i] = best
    return max(dp)

