def solve(coins, amount):
    """Minimum number of coins to make amount using unlimited positive coin values.
    Returns -1 if impossible. Handles edge cases like empty coin list, negative amount,
    and filters out non-positive coin denominations.
    """
    if amount < 0:
        return -1
    # Filter out non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return 0 if amount == 0 else -1
    # If 1 is present, answer is amount (using 1-unit coins)
    if 1 in coins:
        return amount
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = max_val
        for c in coins:
            if c <= a:
                prev = dp[a - c]
                if prev + 1 < best:
                    best = prev + 1
        dp[a] = best
    return dp[amount] if dp[amount] != max_val else -1

