def solve(nums):
    """Return length of longest strictly increasing subsequence in nums.
    Uses patience sorting with binary search for O(n log n) time.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find insertion point: first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

